import { TUI_AGENT_CONFIG } from './tui-agent-config'
import type { TuiAgent } from './tui-agent'

export type AgentPermissionMode = 'yolo' | 'manual' | 'mixed'

export const YOLO_TUI_AGENT_ARGS: Partial<Record<TuiAgent, string>> = {
  claude: '--dangerously-skip-permissions',
  codebuddy: '--dangerously-skip-permissions',
  'claude-agent-teams': '--dangerously-skip-permissions',
  openclaude: '--dangerously-skip-permissions',
  codex: '--dangerously-bypass-approvals-and-sandbox',
  qoder: '--dangerously-skip-permissions',
  'qoder-cn': '--dangerously-skip-permissions',
  gemini: '--yolo',
  antigravity: '--dangerously-skip-permissions',
  aider: '--yes-always',
  amp: '--dangerously-allow-all',
  kiro: '--trust-all-tools',
  crush: '--yolo',
  autohand: '--unrestricted',
  cline: '--auto-approve true',
  'command-code': '--yolo',
  continue: '--allow "*"',
  cursor: '--yolo',
  kimi: '--yolo',
  muse: '--yolo',
  // Why: ZCode gates tools by collaboration mode; `yolo` is its bypass-everything mode.
  zcode: '--mode yolo',
  'mistral-vibe': '--agent auto-approve',
  'qwen-code': '--approval-mode yolo',
  rovo: '--yolo',
  hermes: '--yolo',
  copilot: '--yolo',
  grok: '--permission-mode bypassPermissions',
  devin: '--permission-mode bypass --respect-workspace-trust false',
  ante: '--yolo',
  trae: '--yolo',
  droid: '--auto high'
}

export const YOLO_TUI_AGENT_ENV: Partial<Record<TuiAgent, Record<string, string>>> = {
  goose: { GOOSE_MODE: 'auto' }
}

const PERMISSION_AGENT_IDS = Object.keys(TUI_AGENT_CONFIG).filter(
  (agent): agent is TuiAgent => agent in YOLO_TUI_AGENT_ARGS || agent in YOLO_TUI_AGENT_ENV
)

function normalizeArgs(value: string | null | undefined): string {
  return value?.trim() ?? ''
}

function sameEnv(
  left: Record<string, string> | null | undefined,
  right: Record<string, string> | null | undefined
): boolean {
  const leftEntries = Object.entries(left ?? {})
  const rightEntries = Object.entries(right ?? {})
  if (leftEntries.length !== rightEntries.length) {
    return false
  }
  return leftEntries.every(([name, value]) => right?.[name] === value)
}

function resolveAgentPermissionMode(args: string, yoloArgs: string): AgentPermissionMode {
  if (!args) {
    return 'manual'
  }
  return args === yoloArgs ? 'yolo' : 'mixed'
}

function resolveAgentEnvPermissionMode(
  env: Record<string, string> | null | undefined,
  yoloEnv: Record<string, string> | undefined
): AgentPermissionMode {
  if (sameEnv(env, {})) {
    return 'manual'
  }
  return sameEnv(env, yoloEnv) ? 'yolo' : 'mixed'
}

function combinePermissionModes(modes: AgentPermissionMode[]): AgentPermissionMode {
  let sawYolo = false
  let sawManual = false
  let sawMixed = false

  for (const mode of modes) {
    if (mode === 'yolo') {
      sawYolo = true
    } else if (mode === 'manual') {
      sawManual = true
    } else {
      sawMixed = true
    }
  }

  if (sawMixed || (sawYolo && sawManual)) {
    return 'mixed'
  }
  return sawYolo ? 'yolo' : 'manual'
}

export function resolveTuiAgentPermissionMode(args: {
  agent: TuiAgent
  agentArgs?: string | null
  agentEnv?: Record<string, string> | null
}): AgentPermissionMode {
  const modes: AgentPermissionMode[] = []
  if (args.agent in YOLO_TUI_AGENT_ARGS) {
    modes.push(
      resolveAgentPermissionMode(
        normalizeArgs(args.agentArgs),
        YOLO_TUI_AGENT_ARGS[args.agent] ?? ''
      )
    )
  }
  if (args.agent in YOLO_TUI_AGENT_ENV) {
    modes.push(resolveAgentEnvPermissionMode(args.agentEnv, YOLO_TUI_AGENT_ENV[args.agent]))
  }

  return combinePermissionModes(modes)
}

export function resolveAgentPermissionModeSummary(args: {
  agentDefaultArgs?: Partial<Record<TuiAgent, string>> | null
  agentDefaultEnv?: Partial<Record<TuiAgent, Record<string, string>>> | null
}): AgentPermissionMode {
  const modes: AgentPermissionMode[] = []

  for (const agent of PERMISSION_AGENT_IDS) {
    modes.push(
      resolveTuiAgentPermissionMode({
        agent,
        agentArgs: args.agentDefaultArgs?.[agent],
        agentEnv: args.agentDefaultEnv?.[agent]
      })
    )
  }

  return combinePermissionModes(modes)
}

export function applyAgentPermissionMode(args: {
  mode: Exclude<AgentPermissionMode, 'mixed'>
  agentDefaultArgs?: Partial<Record<TuiAgent, string>> | null
  agentDefaultEnv?: Partial<Record<TuiAgent, Record<string, string>>> | null
}): {
  agentDefaultArgs: Partial<Record<TuiAgent, string>>
  agentDefaultEnv: Partial<Record<TuiAgent, Record<string, string>>>
} {
  const nextArgs = { ...args.agentDefaultArgs }
  const nextEnv = { ...args.agentDefaultEnv }

  for (const agent of PERMISSION_AGENT_IDS) {
    if (agent in YOLO_TUI_AGENT_ARGS) {
      const yoloArgs = YOLO_TUI_AGENT_ARGS[agent] ?? ''
      const currentArgs = normalizeArgs(nextArgs[agent])
      if (!currentArgs || currentArgs === yoloArgs) {
        nextArgs[agent] = args.mode === 'yolo' ? yoloArgs : ''
      }
    }

    if (agent in YOLO_TUI_AGENT_ENV) {
      const yoloEnv = YOLO_TUI_AGENT_ENV[agent]
      const currentEnv = nextEnv[agent]
      if (sameEnv(currentEnv, {}) || sameEnv(currentEnv, yoloEnv)) {
        nextEnv[agent] = args.mode === 'yolo' ? { ...yoloEnv } : {}
      }
    }
  }

  return { agentDefaultArgs: nextArgs, agentDefaultEnv: nextEnv }
}

import type { GlobalSettings } from './global-settings-types'
import { isTuiAgent } from './tui-agent-config'
import { YOLO_TUI_AGENT_ARGS, YOLO_TUI_AGENT_ENV } from './tui-agent-permissions'
import {
  resolveStartupShell,
  tokenizeStartupCommand,
  type AgentStartupShell
} from './tui-agent-startup-shell'
import type { TuiAgent } from './tui-agent'
import { resolveLocalWindowsAgentStartupShell } from './windows-terminal-shell'

const UNSUPPORTED_TUI_AGENT_ARGS: Partial<Record<TuiAgent, readonly string[]>> = {
  opencode: ['--dangerously-skip-permissions'],
  kilo: ['--dangerously-skip-permissions']
}

export const DEFAULT_TUI_AGENT_ARGS: Partial<Record<TuiAgent, string>> = YOLO_TUI_AGENT_ARGS

export const DEFAULT_TUI_AGENT_ENV: Partial<Record<TuiAgent, Record<string, string>>> =
  YOLO_TUI_AGENT_ENV

function argPattern(arg: string): RegExp {
  return new RegExp(`(^|\\s)${arg.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?=\\s|$)`, 'g')
}

export function hasUnsupportedTuiAgentArgs(agent: TuiAgent, value: unknown): boolean {
  if (typeof value !== 'string') {
    return false
  }
  return (UNSUPPORTED_TUI_AGENT_ARGS[agent] ?? []).some((arg) => argPattern(arg).test(value))
}

/**
 * Whether the configured arguments carry this agent's permission-bypass flag.
 *
 * The Agent Permissions toggle has no storage of its own — it writes and reads this flag inside
 * the arguments string. Read the same argv the startup path builds so quoted prompt text and
 * operands after `--` cannot authorize a structured session.
 */
export function tuiAgentArgsBypassPermissions(
  agent: TuiAgent,
  value: string | null | undefined,
  shell: AgentStartupShell
): boolean {
  const bypassArg = YOLO_TUI_AGENT_ARGS[agent]
  if (typeof value !== 'string' || bypassArg === undefined) {
    return false
  }
  const tokenized = tokenizeStartupCommand(value, shell)
  const bypass = tokenizeStartupCommand(bypassArg, shell)
  if (!tokenized.ok || !bypass.ok || bypass.tokens.length === 0) {
    return false
  }
  const terminator = tokenized.tokens.indexOf('--')
  const options = terminator === -1 ? tokenized.tokens : tokenized.tokens.slice(0, terminator)
  // A token sequence: several agents' bypass is a flag and its value (`--permission-mode X`).
  return options.some((_, start) =>
    bypass.tokens.every((token, offset) => options[start + offset] === token)
  )
}

function sanitizeTuiAgentLaunchArgs(agent: TuiAgent, args: string): string {
  const unsupportedArgs = UNSUPPORTED_TUI_AGENT_ARGS[agent]
  if (!unsupportedArgs) {
    return args.trim()
  }
  // Why: a few agents have removed, relocated, or never exposed Claude-style
  // skip-permission flags on the interactive TUI command Orca launches.
  return unsupportedArgs.reduce((next, arg) => next.replace(argPattern(arg), ' '), args).trim()
}

export function normalizeTuiAgentArgsRecord(value: unknown): Partial<Record<TuiAgent, string>> {
  const normalized: Partial<Record<TuiAgent, string>> = {}
  if (!value || typeof value !== 'object') {
    return normalized
  }
  for (const [agent, args] of Object.entries(value)) {
    if (!isTuiAgent(agent) || typeof args !== 'string') {
      continue
    }
    normalized[agent] = sanitizeTuiAgentLaunchArgs(agent, args)
  }
  return normalized
}

export function normalizeTuiAgentEnvRecord(
  value: unknown
): Partial<Record<TuiAgent, Record<string, string>>> {
  const normalized: Partial<Record<TuiAgent, Record<string, string>>> = {}
  if (!value || typeof value !== 'object') {
    return normalized
  }
  for (const [agent, env] of Object.entries(value)) {
    if (!isTuiAgent(agent) || !env || typeof env !== 'object') {
      continue
    }
    const nextEnv: Record<string, string> = {}
    for (const [name, raw] of Object.entries(env)) {
      const key = name.trim()
      if (!key || typeof raw !== 'string') {
        continue
      }
      nextEnv[key] = raw
    }
    normalized[agent] = nextEnv
  }
  return normalized
}

export function getTuiAgentDefaultArgs(agent: TuiAgent): string {
  return DEFAULT_TUI_AGENT_ARGS[agent] ?? ''
}

export function getTuiAgentDefaultEnv(agent: TuiAgent): Record<string, string> {
  return { ...DEFAULT_TUI_AGENT_ENV[agent] }
}

export function resolveTuiAgentLaunchArgs(
  agent: TuiAgent,
  configuredArgs: Partial<Record<TuiAgent, string>> | null | undefined
): string {
  if (
    configuredArgs &&
    Object.hasOwn(configuredArgs, agent) &&
    typeof configuredArgs[agent] === 'string'
  ) {
    return configuredArgs[agent] ?? ''
  }
  return getTuiAgentDefaultArgs(agent)
}

/**
 * Whether this agent's *resolved* launch arguments ask for a permission bypass.
 *
 * Resolved, not configured: an untouched Arguments field falls back to the default Orca ships,
 * which is the bypass flag, so bypass is the posture a user gets until they choose otherwise.
 * Choosing Manual stores an empty string, which owns the key and so beats that default.
 */
export function resolvedTuiAgentArgsBypassPermissions(
  agent: TuiAgent,
  settings:
    | Partial<Pick<GlobalSettings, 'agentDefaultArgs' | 'terminalWindowsShell'>>
    | null
    | undefined,
  platform: NodeJS.Platform
): boolean {
  const shell = resolveStartupShell(
    platform,
    resolveLocalWindowsAgentStartupShell({
      platform,
      isRemote: false,
      terminalWindowsShell: settings?.terminalWindowsShell
    })
  )
  return tuiAgentArgsBypassPermissions(
    agent,
    resolveTuiAgentLaunchArgs(agent, settings?.agentDefaultArgs),
    shell
  )
}

export function resolveTuiAgentLaunchEnv(
  agent: TuiAgent,
  configuredEnv: Partial<Record<TuiAgent, Record<string, string>>> | null | undefined
): Record<string, string> {
  if (configuredEnv && Object.hasOwn(configuredEnv, agent)) {
    return { ...configuredEnv[agent] }
  }
  return getTuiAgentDefaultEnv(agent)
}

import type { GlobalSettings, OrcaWorkspaceLayout } from '../../../shared/global-settings-types'
import { normalizeRuntimePathForComparison } from '../../../shared/cross-platform-path'
import {
  legacyTerminalScrollbackBytesToRows,
  normalizeDesktopTerminalScrollbackRows
} from '../../../shared/terminal-scrollback-policy'
import {
  DEFAULT_TUI_AGENT_ARGS,
  DEFAULT_TUI_AGENT_ENV,
  normalizeTuiAgentArgsRecord,
  normalizeTuiAgentEnvRecord
} from '../../../shared/tui-agent-launch-defaults'

export function buildWorkspaceDirHistoryForUpdate(
  current: GlobalSettings,
  updates: Partial<GlobalSettings>
): OrcaWorkspaceLayout[] | null {
  if (!('workspaceDir' in updates) && !('nestWorkspaces' in updates)) {
    return null
  }
  const nextPath = updates.workspaceDir ?? current.workspaceDir
  const nextNestWorkspaces = updates.nestWorkspaces ?? current.nestWorkspaces
  if (
    normalizeRuntimePathForComparison(nextPath) ===
      normalizeRuntimePathForComparison(current.workspaceDir) &&
    nextNestWorkspaces === current.nestWorkspaces
  ) {
    return null
  }

  const previousLayout = {
    path: current.workspaceDir,
    nestWorkspaces: current.nestWorkspaces
  }
  const existing = current.workspaceDirHistory ?? []
  const next = [...existing]
  const previousKey = getWorkspaceLayoutHistoryKey(previousLayout)
  if (!next.some((layout) => getWorkspaceLayoutHistoryKey(layout) === previousKey)) {
    next.push(previousLayout)
  }
  return next
}

export type LegacyTerminalScrollbackSettings = {
  terminalScrollbackRows?: unknown
  terminalScrollbackBytes?: unknown
}

export const LEGACY_TERMINAL_TUI_SCROLL_SENSITIVITY_DEFAULT = 3

export function readLegacyTerminalScrollbackSettings(
  settings: unknown
): LegacyTerminalScrollbackSettings {
  return settings && typeof settings === 'object'
    ? (settings as LegacyTerminalScrollbackSettings)
    : {}
}

type RetiredGlobalSettings = {
  terminalScrollbackBytes?: unknown
  enableGitHubAttribution?: unknown
  showAgentsSidebar?: unknown
  // Managed servers are the default SSH path now; an older build reads a missing key as off.
  experimentalManagedServers?: unknown
  // Why: #22551 kept this key in settings; it now lives in a main-owned store and must never ride along.
  opencodeGoApiKey?: unknown
  experimentalStructuredNativeChat?: unknown
  openAgentTabsInChatByDefault?: unknown
}

export function stripRetiredGlobalSettings(
  settings: Partial<GlobalSettings> | undefined
): Partial<GlobalSettings> {
  const {
    terminalScrollbackBytes: _legacyScrollbackBytes,
    enableGitHubAttribution: _legacyGitHubAttribution,
    showAgentsSidebar: _legacyShowAgentsSidebar,
    experimentalManagedServers: _retiredManagedServersExperiment,
    opencodeGoApiKey: _legacyOpenCodeGoApiKey,
    experimentalStructuredNativeChat: _legacyStructuredNativeChat,
    openAgentTabsInChatByDefault: _legacyChatDefaultView,
    ...rest
  } = (settings ?? {}) as Partial<GlobalSettings> & RetiredGlobalSettings
  void _legacyScrollbackBytes
  void _legacyGitHubAttribution
  void _legacyShowAgentsSidebar
  void _retiredManagedServersExperiment
  void _legacyOpenCodeGoApiKey
  void _legacyStructuredNativeChat
  void _legacyChatDefaultView
  return rest
}

/**
 * Chat UI was on but the retired Default view left new agent tabs in the terminal. Every build
 * before the retirement saved that key, so a profile without it was already upgraded.
 */
export function savedChatUiWithTerminalDefaultView(settings: unknown): boolean {
  return (
    typeof settings === 'object' &&
    settings !== null &&
    'experimentalNativeChat' in settings &&
    settings.experimentalNativeChat === true &&
    'openAgentTabsInChatByDefault' in settings &&
    settings.openAgentTabsInChatByDefault !== true
  )
}

export function migrateTerminalScrollbackRows(settings: unknown): {
  rows: number
  needsSave: boolean
} {
  const legacySettings = readLegacyTerminalScrollbackSettings(settings)
  const hasRows = Object.hasOwn(legacySettings, 'terminalScrollbackRows')
  const hasLegacyBytes = Object.hasOwn(legacySettings, 'terminalScrollbackBytes')
  const rows = hasRows
    ? normalizeDesktopTerminalScrollbackRows(legacySettings.terminalScrollbackRows)
    : legacyTerminalScrollbackBytesToRows(legacySettings.terminalScrollbackBytes)

  return {
    rows,
    needsSave: !hasRows || hasLegacyBytes || legacySettings.terminalScrollbackRows !== rows
  }
}

export function migrateTerminalTuiScrollSensitivityDefault(settings: GlobalSettings | undefined): {
  settings: Pick<
    GlobalSettings,
    'terminalTuiScrollSensitivity' | 'terminalTuiScrollSensitivityDefaultedToOne'
  >
  needsSave: boolean
} {
  const alreadyDefaultedToOne = settings?.terminalTuiScrollSensitivityDefaultedToOne === true
  const current = settings?.terminalTuiScrollSensitivity
  const shouldMoveInheritedDefault =
    !alreadyDefaultedToOne &&
    (current === undefined || current === LEGACY_TERMINAL_TUI_SCROLL_SENSITIVITY_DEFAULT)
  const terminalTuiScrollSensitivity = shouldMoveInheritedDefault ? 1 : (current ?? 1)

  return {
    settings: {
      terminalTuiScrollSensitivity,
      terminalTuiScrollSensitivityDefaultedToOne: true
    },
    needsSave: !alreadyDefaultedToOne || current === undefined
  }
}

export function getWorkspaceLayoutHistoryKey(layout: OrcaWorkspaceLayout): string {
  return `${normalizeRuntimePathForComparison(layout.path)}:${layout.nestWorkspaces}`
}

export function migrateAgentYoloDefaults(
  settings: GlobalSettings | undefined
): Pick<GlobalSettings, 'agentDefaultArgs' | 'agentDefaultEnv' | 'agentYoloDefaultsMigrated'> {
  const existingArgs = normalizeTuiAgentArgsRecord(settings?.agentDefaultArgs)
  const existingEnv = normalizeTuiAgentEnvRecord(settings?.agentDefaultEnv)
  if (existingArgs.devin === '--permission-mode bypass') {
    existingArgs.devin = DEFAULT_TUI_AGENT_ARGS.devin
  }
  if (settings?.agentYoloDefaultsMigrated === true) {
    // Keep newly added agents manual for profiles migrated by an older build.
    // Missing keys otherwise fall through to the current (possibly yolo) defaults.
    for (const agent of Object.keys(DEFAULT_TUI_AGENT_ARGS)) {
      if (!(agent in existingArgs)) {
        existingArgs[agent as keyof typeof DEFAULT_TUI_AGENT_ARGS] = ''
      }
    }
    for (const agent of Object.keys(DEFAULT_TUI_AGENT_ENV)) {
      if (!(agent in existingEnv)) {
        existingEnv[agent as keyof typeof DEFAULT_TUI_AGENT_ENV] = {}
      }
    }
    return {
      agentDefaultArgs: existingArgs,
      agentDefaultEnv: existingEnv,
      agentYoloDefaultsMigrated: true
    }
  }

  const commandOverrides = settings?.agentCmdOverrides ?? {}
  const migratedArgs = { ...existingArgs }
  for (const [agent, args] of Object.entries(DEFAULT_TUI_AGENT_ARGS)) {
    if (agent in migratedArgs) {
      continue
    }
    if (agent in commandOverrides) {
      migratedArgs[agent as keyof typeof DEFAULT_TUI_AGENT_ARGS] = ''
      continue
    }
    migratedArgs[agent as keyof typeof DEFAULT_TUI_AGENT_ARGS] = args
  }

  const migratedEnv = { ...existingEnv }
  for (const [agent, env] of Object.entries(DEFAULT_TUI_AGENT_ENV)) {
    if (agent in migratedEnv) {
      continue
    }
    if (agent in commandOverrides) {
      migratedEnv[agent as keyof typeof DEFAULT_TUI_AGENT_ENV] = {}
      continue
    }
    migratedEnv[agent as keyof typeof DEFAULT_TUI_AGENT_ENV] = { ...env }
  }

  return {
    // Why: legacy users could only customize launch defaults via command overrides, so those agents count as already user-owned.
    agentDefaultArgs: migratedArgs,
    agentDefaultEnv: migratedEnv,
    agentYoloDefaultsMigrated: true
  }
}

import { TUI_AGENT_CONFIG, isTuiAgent } from '../shared/tui-agent-config'
import type { GlobalSettings } from '../shared/global-settings-types'
import { resolveTerminalWorkspacePath } from '../shared/terminal-startup-cwd'
import {
  applyAgentWorkspaceTrust,
  type AgentTrustLaunchContext,
  type AgentTrustSpawnFields
} from './agent-workspace-trust'
import { AGENT_TRUST_KEYED_BY_START_FOLDER } from './execution-host-workspace-trust'

type AgentWorkspaceTrustSetting =
  | Pick<GlobalSettings, 'agentWorkspaceTrustEnabled'>
  | null
  | undefined

function isAgentWorkspaceTrustOn(settings: AgentWorkspaceTrustSetting): boolean {
  return settings?.agentWorkspaceTrustEnabled !== false
}

/**
 * The one place Orca pre-trusts a workspace: every Orca-started agent PTY passes
 * through a spawn builder with its declared `launchAgent`, which survives setup-script
 * wrapping. Reattaches and restores are skipped so trust is never re-run for them.
 * Structured Codex chats have no PTY and enter below instead. Returns null when there is nothing to write, so other spawns take no extra tick:
 * the builders arbitrate pane-spawn reservation races that a tick can reorder.
 */
export function applyAgentWorkspaceTrustToSpawn(
  args: {
    launchAgent: unknown
    /** Worktree or folder workspace id; its root is the folder the agent is trusted in. */
    worktreeId: string | undefined
    /** The resolved folder the agent starts in; floating terminals have only this. */
    cwd: string | undefined
    store: { getFolderWorkspace: (id: string) => { folderPath: string } | undefined } | undefined
    isFreshLaunch: boolean
    settings: AgentWorkspaceTrustSetting
    spawnOptions: AgentTrustSpawnFields
  } & AgentTrustLaunchContext
): Promise<void> | null {
  if (!args.isFreshLaunch || !isAgentWorkspaceTrustOn(args.settings)) {
    return null
  }
  const preset = isTuiAgent(args.launchAgent)
    ? TUI_AGENT_CONFIG[args.launchAgent].preflightTrust
    : undefined
  if (!preset) {
    return null
  }
  const workspaceRoot = resolveTerminalWorkspacePath(
    args.worktreeId,
    (folderWorkspaceId) => args.store?.getFolderWorkspace(folderWorkspaceId)?.folderPath
  )
  const workspacePath = AGENT_TRUST_KEYED_BY_START_FOLDER[preset]
    ? args.cwd || workspaceRoot
    : workspaceRoot
  if (!workspacePath) {
    return null
  }
  return applyAgentWorkspaceTrust(preset, workspacePath, {
    env: args.env,
    claudeAuth: args.claudeAuth,
    wslDistro: args.wslDistro,
    connectionId: args.connectionId
  }).then((fields) => {
    if (fields.agentWorkspaceTrust) {
      args.spawnOptions.agentWorkspaceTrust = fields.agentWorkspaceTrust
    }
  })
}

/**
 * Structured Codex chats are the one agent start with no PTY. Codex's app-server trusts the
 * folder itself only when the chat may write it, so a read-only chat would ignore `.codex` config.
 */
export async function applyStructuredCodexWorkspaceTrust(args: {
  workspacePath: string
  launchEnv: Record<string, string | undefined>
  settings: AgentWorkspaceTrustSetting
}): Promise<void> {
  if (!isAgentWorkspaceTrustOn(args.settings)) {
    return
  }
  await applyAgentWorkspaceTrust('codex', args.workspacePath, {
    env: args.launchEnv,
    claudeAuth: null,
    wslDistro: null,
    connectionId: null
  })
}

import { normalizeRuntimePathForComparison } from '../../../../shared/cross-platform-path'
import type { GlobalSettings } from '../../../../shared/global-settings-types'
import {
  isCodexHomeAuthReadyForLaunch,
  waitForManagedCodexAuthReady
} from '../../../codex-accounts/managed-codex-auth-readiness'
import type { CodexAccountSelectionTarget } from '../../../codex-accounts/runtime-selection'
import {
  forgetCodexPaneAccount,
  getCodexPaneAccount,
  recordCodexPaneAccount,
  type CodexPaneHomeRoute
} from '../../../codex/codex-pane-account-registry'
import { resolveCodexPaneLaunchAccount } from '../../../codex/codex-pane-launch-account'
import { getSystemCodexHomePath } from '../../../codex/codex-home-paths'
import { isHostCodexHomeForWsl, isWslCodexHomeForHost } from '../../../pty/codex-home-wsl-env'
import { isWslShellName } from '../../../../shared/local-windows-terminal-runtime'
import { parseWslPath } from '../../../wsl'

export function shouldSkipCodexHomeEnvForWindowsShell(
  shellPath: string | undefined,
  cwd: string | undefined
): boolean {
  return isWslShellName(shellPath) || (typeof cwd === 'string' && parseWslPath(cwd) !== null)
}

// Why: with the real-home flag ON, a host system-default launch resolves to a
// null managed home. Signal the env builder to strip a nested-Orca-inherited
// override instead of injecting one, so Codex runs on the user's own ~/.codex.
export function shouldStripInheritedOrcaCodexHome(args: {
  target: CodexAccountSelectionTarget
  selectedCodexHomePath: string | null
  skipCodexHomeEnv: boolean
  settings: GlobalSettings | undefined
}): boolean {
  return (
    args.target.runtime === 'host' && args.selectedCodexHomePath === null && !args.skipCodexHomeEnv
  )
}

export const CODEX_HOME_ENV_KEYS = ['CODEX_HOME', 'ORCA_CODEX_HOME'] as const

// Why: system-default real-home routing runs Codex on the user's own ~/.codex.
// Nested Orca panes inherit the parent's Orca-owned override; strip only that
// (CODEX_HOME matching Orca's private ORCA_CODEX_HOME marker), and always drop
// the marker so a shell-ready wrapper cannot restore the managed home. A
// user-set CODEX_HOME with no Orca marker is preserved untouched (see #8606).
export function stripInheritedOrcaCodexHomeOverride(baseEnv: Record<string, string>): void {
  for (const key of getLocalOrcaCodexHomeEnvKeysToDelete(baseEnv)) {
    delete baseEnv[key]
  }
}

// Why: in-process spawns share main's inherited environment, so equality with
// the private marker is authoritative here. Persistent daemons compare locally.
export function getLocalOrcaCodexHomeEnvKeysToDelete(env: Record<string, string>): string[] {
  const inheritedOrcaOverride = env.ORCA_CODEX_HOME ?? process.env.ORCA_CODEX_HOME
  const inheritedCodexHome = env.CODEX_HOME ?? process.env.CODEX_HOME
  const keysToDelete = ['ORCA_CODEX_HOME']
  if (inheritedOrcaOverride && inheritedCodexHome === inheritedOrcaOverride) {
    keysToDelete.push('CODEX_HOME')
  }
  return keysToDelete
}

export function getCodexSelectionTargetForPty(
  shellPath: string | undefined,
  cwd: string | undefined,
  wslDistro?: string | null
): CodexAccountSelectionTarget {
  const wslPath = typeof cwd === 'string' ? parseWslPath(cwd) : null
  if (isWslShellName(shellPath) || wslPath) {
    return { runtime: 'wsl', wslDistro: wslPath?.distro ?? wslDistro ?? null }
  }
  return { runtime: 'host' }
}

export function getCompatibleSelectedCodexHomePath(
  target: CodexAccountSelectionTarget,
  selectedCodexHomePath: string | null
): string | null {
  if (!selectedCodexHomePath) {
    return null
  }
  const wslInfo = parseWslPath(selectedCodexHomePath)
  if (target.runtime === 'wsl') {
    return wslInfo || !isHostCodexHomeForWsl(selectedCodexHomePath) ? selectedCodexHomePath : null
  }
  return wslInfo || (process.platform === 'win32' && isWslCodexHomeForHost(selectedCodexHomePath))
    ? null
    : selectedCodexHomePath
}

export const MANAGED_CODEX_AUTH_UNAVAILABLE_MESSAGE =
  'The selected Codex account credentials are temporarily unavailable. Try opening the terminal again.'
export const CODEX_RESUME_AUTH_UNAVAILABLE_MESSAGE =
  'The Codex account credentials for this session are temporarily unavailable. Try opening the terminal again.'

type ManagedCodexAuthResolutionArgs = {
  selectedCodexHomePath: string | null
  getSettings: () => GlobalSettings | undefined
  requiredCodexHomePath?: string
  target: CodexAccountSelectionTarget
  resolveCurrent: () => string | null | Promise<string | null>
  resolveAfterUnavailable: (
    unavailableManagedHomePath: string
  ) => string | null | Promise<string | null>
}

export function resolveCodexHomeAfterManagedAuthReadiness(
  args: ManagedCodexAuthResolutionArgs
): string | null | Promise<string | null> {
  const selectedCodexHomePath = args.selectedCodexHomePath
  if (
    args.requiredCodexHomePath &&
    !codexHomePathsEqual(selectedCodexHomePath, args.requiredCodexHomePath)
  ) {
    throw new Error(CODEX_RESUME_AUTH_UNAVAILABLE_MESSAGE)
  }
  const readiness = waitForManagedCodexAuthReady({
    codexHomePath: selectedCodexHomePath,
    settings: args.getSettings(),
    target: args.target
  })
  return readiness
    ? continueCodexHomeAfterManagedAuthWait(args, selectedCodexHomePath, readiness)
    : selectedCodexHomePath
}

async function continueCodexHomeAfterManagedAuthWait(
  args: ManagedCodexAuthResolutionArgs,
  initialCodexHomePath: string | null,
  initialReadiness: Promise<boolean>
): Promise<string | null> {
  let selectedCodexHomePath = initialCodexHomePath
  let readiness = initialReadiness
  for (let attempt = 0; attempt < 2; attempt += 1) {
    if (await readiness) {
      if (args.requiredCodexHomePath) {
        return selectedCodexHomePath
      }
      const currentCodexHomePath = await args.resolveCurrent()
      if (codexHomeSelectionsEqual(selectedCodexHomePath, currentCodexHomePath)) {
        return selectedCodexHomePath
      }
      selectedCodexHomePath = currentCodexHomePath
      if (attempt === 1) {
        break
      }
      const nextReadiness = waitForManagedCodexAuthReady({
        codexHomePath: selectedCodexHomePath,
        settings: args.getSettings(),
        target: args.target
      })
      if (!nextReadiness) {
        return selectedCodexHomePath
      }
      readiness = nextReadiness
      continue
    }
    if (args.requiredCodexHomePath) {
      throw new Error(CODEX_RESUME_AUTH_UNAVAILABLE_MESSAGE)
    }
    selectedCodexHomePath = await args.resolveAfterUnavailable(selectedCodexHomePath!)
    if (attempt === 1) {
      break
    }
    const nextReadiness = waitForManagedCodexAuthReady({
      codexHomePath: selectedCodexHomePath,
      settings: args.getSettings(),
      target: args.target
    })
    if (!nextReadiness) {
      return selectedCodexHomePath
    }
    readiness = nextReadiness
  }
  if (
    isCodexHomeAuthReadyForLaunch({
      codexHomePath: selectedCodexHomePath,
      settings: args.getSettings(),
      target: args.target
    })
  ) {
    return selectedCodexHomePath
  }
  throw new Error(MANAGED_CODEX_AUTH_UNAVAILABLE_MESSAGE)
}

export function codexHomeSelectionsEqual(left: string | null, right: string | null): boolean {
  return (
    left === right ||
    (left !== null &&
      right !== null &&
      normalizeRuntimePathForComparison(left) === normalizeRuntimePathForComparison(right))
  )
}

export function codexHomePathsEqual(left: string | null, right: string): boolean {
  return codexHomeSelectionsEqual(left, right)
}

// Why: CODEX_HOME is fixed in a shell's environment at spawn and the daemon
// keeps that shell alive across app restarts, so the launch account is the only
// way to tell later that a pane still runs Codex as the previously selected
// account. A reattach inherits that baked environment rather than choosing one,
// so re-recording it under the current selection would erase the very evidence
// that the pane is stale.
export function recordCodexPaneAccountForSpawn(args: {
  ptyId: string | undefined
  isDaemonHostSpawn: boolean
  isReattach: boolean
  pinnedByResume: boolean
  launchCodexHomePath: string | null
  target: CodexAccountSelectionTarget
  settings: GlobalSettings | undefined
}): void {
  if (!args.ptyId || !args.isDaemonHostSpawn || args.isReattach) {
    return
  }
  const record = args.settings
    ? resolveCodexPaneLaunchAccount({
        pinnedByResume: args.pinnedByResume,
        launchCodexHomePath: args.launchCodexHomePath,
        systemCodexHomePath: getSystemCodexHomePath(),
        settings: args.settings,
        target: args.target
      })
    : null
  if (!record) {
    forgetCodexPaneAccount(args.ptyId)
    return
  }
  recordCodexPaneAccount(args.ptyId, record)
}

export function snapshotCodexPaneHomeRoutes(
  ptyIds: readonly (string | null | undefined)[]
): ReadonlyMap<string, CodexPaneHomeRoute | null> {
  const routes = new Map<string, CodexPaneHomeRoute | null>()
  for (const ptyId of ptyIds) {
    if (!ptyId || routes.has(ptyId)) {
      continue
    }
    routes.set(ptyId, getCodexPaneAccount(ptyId)?.homeRoute ?? null)
  }
  return routes
}

export function codexReattachedHomeRouteField(
  routes: ReadonlyMap<string, CodexPaneHomeRoute | null>,
  ptyId: string,
  reattached: boolean
): { reattachedHomeRoute?: CodexPaneHomeRoute | null } {
  if (!reattached || !routes.has(ptyId)) {
    return {}
  }
  return { reattachedHomeRoute: routes.get(ptyId) ?? null }
}

import { createHash } from 'node:crypto'

export type ProfileStateDocument = {
  domain: string
  payload: string
  domainVersion: number
  revision: number
  updatedAt: number
  contentHash: string
}

export type ProfileStateValidatedDocument = Omit<ProfileStateDocument, 'payload'>
export type ProfileStateParsedDocument = ProfileStateValidatedDocument & { value: unknown }

export class ProfileStateDocumentCorruptionError extends Error {
  readonly code = 'corrupt-document' as const
  readonly domain: string | null

  constructor(message: string, domain: string | null = null) {
    super(message)
    this.name = 'ProfileStateDocumentCorruptionError'
    this.domain = domain
  }
}

export class ProfileStateRevisionConflictError extends Error {
  readonly code = 'profile-state-revision-conflict' as const
  readonly expectedRevision: number
  readonly actualRevision: number

  constructor(expectedRevision: number, actualRevision: number) {
    super(
      `Profile state revision changed while importing a document (expected ${expectedRevision}, found ${actualRevision})`
    )
    this.name = 'ProfileStateRevisionConflictError'
    this.expectedRevision = expectedRevision
    this.actualRevision = actualRevision
  }
}

export function hashProfileStatePayload(payload: string): string {
  return createHash('sha256').update(payload, 'utf8').digest('hex')
}

export function parseProfileStateRoot(rawJson: string): Record<string, unknown> {
  let parsed: unknown
  try {
    parsed = JSON.parse(rawJson)
  } catch {
    throw new ProfileStateDocumentCorruptionError('Profile state JSON is invalid', null)
  }
  if (!isRecord(parsed)) {
    throw new ProfileStateDocumentCorruptionError('Profile state JSON root must be an object', null)
  }
  return parsed
}

export function validateProfileStateDocumentRow(
  row: unknown,
  options: { validateJson?: boolean; retainParsedValue?: boolean } = {}
): ProfileStateDocument & { value?: unknown } {
  if (
    !isRecord(row) ||
    typeof row.domain !== 'string' ||
    typeof row.payload !== 'string' ||
    typeof row.domain_version !== 'number' ||
    typeof row.revision !== 'number' ||
    typeof row.updated_at !== 'number' ||
    typeof row.content_hash !== 'string'
  ) {
    throw new ProfileStateDocumentCorruptionError('Profile state document row has invalid fields')
  }
  if (
    !Number.isSafeInteger(row.domain_version) ||
    row.domain_version < 1 ||
    !Number.isSafeInteger(row.revision) ||
    row.revision < 1 ||
    !Number.isSafeInteger(row.updated_at) ||
    row.updated_at < 0 ||
    !/^[a-f0-9]{64}$/.test(row.content_hash)
  ) {
    throw new ProfileStateDocumentCorruptionError(
      `Profile state document row metadata is invalid: ${row.domain}`,
      row.domain
    )
  }
  if (hashProfileStatePayload(row.payload) !== row.content_hash) {
    throw new ProfileStateDocumentCorruptionError(
      `Profile state document hash mismatch: ${row.domain}`,
      row.domain
    )
  }
  let value: unknown
  if (options.retainParsedValue || (options.validateJson ?? true)) {
    try {
      value = JSON.parse(row.payload)
    } catch {
      throw new ProfileStateDocumentCorruptionError(
        `Profile state document payload is invalid JSON: ${row.domain}`,
        row.domain
      )
    }
  }
  return {
    domain: row.domain,
    payload: row.payload,
    domainVersion: row.domain_version,
    revision: row.revision,
    updatedAt: row.updated_at,
    contentHash: row.content_hash,
    ...(options.retainParsedValue ? { value } : {})
  }
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}
